create function public.test_assert(p boolean,m text) returns void language plpgsql as $$begin if not coalesce(p,false) then raise exception 'ASSERTION: %',m;end if;end$$;
create function public.test_denied(command text) returns void language plpgsql as $$begin begin execute command;exception when others then return;end;raise exception 'Expected rejection: %',command;end$$;
set role anon;
select public.test_denied('select * from public.partnership_commitments');
select public.test_denied($q$select public.join_partnership('10000000-0000-4000-8000-000000000001','Example Partner','clt','weekly','manual','NGN',100,current_date,true,false)$q$);
reset role;
set role authenticated;
set request.jwt.claim.sub='00000000-0000-4000-8000-000000000001';
set test.workspace='';
select public.join_partnership('10000000-0000-4000-8000-000000000001','Example Partner','clt','weekly','manual','NGN',100,current_date,true,false);
select public.join_partnership('10000000-0000-4000-8000-000000000001','Example Partner','clt','weekly','manual','NGN',100,current_date,true,false);
select public.test_assert((select count(*)=1 from public.partnership_commitments),'Join retry duplicated commitment');
