select public.report_partnership_gift('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001',100,'DEMO-REFERENCE-1');
select public.report_partnership_gift('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001',100,'DEMO-REFERENCE-1');
select public.test_assert((select count(*)=1 from public.partnership_gifts),'Gift retry duplicated');
select public.test_denied($q$select public.review_partnership_gift('20000000-0000-4000-8000-000000000001',true)$q$);
select public.test_denied($q$select public.apply_partnership_payment('forged',1,'10000000-0000-4000-8000-000000000001','cus_demo',null,'paid','forged',100,'NGN')$q$);
set request.jwt.claim.sub='00000000-0000-4000-8000-000000000002';
select public.test_assert((select count(*)=0 from public.partnership_commitments),'Other partner sees commitments');
select public.test_assert((select count(*)=0 from public.partnership_gifts),'Other partner sees gifts');
select public.test_denied($q$select public.update_manual_partnership('10000000-0000-4000-8000-000000000001','ended',false)$q$);
select public.test_denied($q$select public.report_partnership_gift('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001',100,'OTHER-REF')$q$);
set test.workspace='media';
select public.test_assert((select count(*)=0 from public.partnership_commitments),'Media sees financial records');
set request.jwt.claim.sub='00000000-0000-4000-8000-000000000003';set test.workspace='pastor';
select public.test_assert((select count(*)=1 from public.partnership_commitments),'Pastor cannot read');
select public.review_partnership_gift('20000000-0000-4000-8000-000000000001',true);
select public.test_assert((select state='received' and confirmed_by=auth.uid() and received_at is not null from public.partnership_gifts limit 1),'Bank confirmation missing');
select public.report_partnership_gift('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001',100,'DEMO-REFERENCE-2');
select public.test_denied($q$select public.review_partnership_gift('20000000-0000-4000-8000-000000000002',true)$q$);
select public.test_denied($q$select public.report_partnership_gift('20000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000001',100,'DEMO-REFERENCE-2')$q$);
