select public.review_partnership_gift('20000000-0000-4000-8000-000000000002',false);
select public.test_assert((select sum(amount)=100 from public.partnership_gifts where state='received'),'Unverified gifts counted as income');
set request.jwt.claim.sub='00000000-0000-4000-8000-000000000001';set test.workspace='';
