select public.test_assert((select count(*)=1 from public.partnership_gifts where provider_key='invoice:in_demo'),'Duplicate provider event double counted');
select public.apply_partnership_payment('evt_cancel',30,'10000000-0000-4000-8000-000000000002','cus_demo','sub_demo','canceled');
